import { Routes, Route } from "react-router-dom";

/* USER WEBSITE */
import Navbar from "./components/Navbar";
import Hero from "./components/Hero";
import Overview from "./components/Overview";
import WhatToExpect from "./components/WhatToExpect";
import TrainingEnvironment from "./components/TrainingEnvironment";
import Programs from "./components/Programs";
import TrainingVideos from "./components/TrainingVideos";
import Gallery from "./components/Gallery";
import Membership from "./components/Membership";
import Trainers from "./components/Trainers";
import Contact from "./components/Contact";
import Review from "./components/Review";

/* ADMIN */
import Login from "./admin/Login";
import Dashboard from "./admin/Dashboard";

function UserSite() {
  return (
    <div id="top" className="bg-black text-white min-h-screen">
      <Navbar />
      <Hero />
      <Overview />
      <WhatToExpect />
      <TrainingEnvironment />

      <section id="programs">
        <Programs />
      </section>

      <section id="training-videos">
        <TrainingVideos />
      </section>

      <section id="gallery">
        <Gallery />
      </section>

      <section id="membership">
        <Membership />
      </section>

      <section id="trainers">
        <Trainers />
      </section>

      <section id="contact">
        <Contact />
      </section>

      <section id="reviews">
        <Review />
      </section>
    </div>
  );
}

export default function App() {
  const token = localStorage.getItem("adminToken");

  return (
    <Routes>
      {/* USER WEBSITE */}
      <Route path="/" element={<UserSite />} />

      {/* ADMIN */}
      <Route path="/admin" element={token ? <Dashboard /> : <Login />} />
    </Routes>
  );
}
